package com.example.starter.web.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 创建公告请求；额度创建后固定。
 */
public class CreateCampaignRequest {

    /** 客户端提供的全局唯一请求编号，用于写操作幂等。 */
    @NotBlank
    @Size(max = 64)
    private String requestId;

    /** 公告业务唯一编号。 */
    @NotBlank
    @Size(max = 64)
    private String campaignId;

    /** 每 UTC 日总额度，1~100000 整数，单位：次。 */
    @NotNull
    @Min(1)
    @Max(100000)
    private Integer dailyTotalCap;

    /** 每访客每 UTC 日上限，1~100000 整数，单位：次。 */
    @NotNull
    @Min(1)
    @Max(100000)
    private Integer visitorCap;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getCampaignId() {
        return campaignId;
    }

    public void setCampaignId(String campaignId) {
        this.campaignId = campaignId;
    }

    public Integer getDailyTotalCap() {
        return dailyTotalCap;
    }

    public void setDailyTotalCap(Integer dailyTotalCap) {
        this.dailyTotalCap = dailyTotalCap;
    }

    public Integer getVisitorCap() {
        return visitorCap;
    }

    public void setVisitorCap(Integer visitorCap) {
        this.visitorCap = visitorCap;
    }
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 曝光申请请求；成功返回 60 秒有效的预占。
 */
public class ApplyExposureRequest {

    /** 客户端提供的全局唯一请求编号，用于写操作幂等。 */
    @NotBlank
    @Size(max = 64)
    private String requestId;

    /** 所属公告编号。 */
    @NotBlank
    @Size(max = 64)
    private String campaignId;

    /** 合成访客编号。 */
    @NotBlank
    @Size(max = 64)
    private String visitorId;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getCampaignId() {
        return campaignId;
    }

    public void setCampaignId(String campaignId) {
        this.campaignId = campaignId;
    }

    public String getVisitorId() {
        return visitorId;
    }

    public void setVisitorId(String visitorId) {
        this.visitorId = visitorId;
    }
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 预占终态操作（确认/取消）请求。
 */
public class ReservationActionRequest {

    /** 客户端提供的全局唯一请求编号，用于写操作幂等。 */
    @NotBlank
    @Size(max = 64)
    private String requestId;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }
}

package com.example.starter.web.dto;

/**
 * 公告响应。
 */
public class CampaignResponse {

    private String campaignId;
    private int dailyTotalCap;
    private int visitorCap;
    /** 创建时刻，UTC 毫秒时间戳。 */
    private long createdAt;

    public CampaignResponse() {
    }

    public CampaignResponse(String campaignId, int dailyTotalCap, int visitorCap, long createdAt) {
        this.campaignId = campaignId;
        this.dailyTotalCap = dailyTotalCap;
        this.visitorCap = visitorCap;
        this.createdAt = createdAt;
    }

    public String getCampaignId() {
        return campaignId;
    }

    public int getDailyTotalCap() {
        return dailyTotalCap;
    }

    public int getVisitorCap() {
