package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类，携带 HTTP 状态码与错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 公告或预占不存在。
 */
public class NotFoundException extends ApiException {

    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 额度已满（公告当日总额度或访客当日额度），对应 HTTP 429。
 */
public class RateLimitException extends ApiException {

    public RateLimitException(String message) {
        super(HttpStatus.TOO_MANY_REQUESTS, "RATE_LIMITED", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 状态冲突：非法状态迁移或幂等键同键异参，对应 HTTP 409。
 */
public class ConflictException extends ApiException {

    public ConflictException(String message) {
        super(HttpStatus.CONFLICT, "CONFLICT", message);
    }
}

package com.example.starter.service;

/**
 * 服务层写操作结果：携带 HTTP 状态码与响应体，
 * 以便幂等重放时原样返回首次成功结果。
 */
public record ServiceResult<T>(int status, T body) {

    public static <T> ServiceResult<T> ok(T body) {
        return new ServiceResult<>(200, body);
    }

    public static <T> ServiceResult<T> created(T body) {
        return new ServiceResult<>(201, body);
    }
}

