 * 释放一次占用；held_count > 0 才生效，返回是否实际释放，杜绝变负/重复释放。
 */
public boolean release(long id) {
    return jdbc.update("""
            UPDATE quota_account SET held_count = held_count - 1
            WHERE id = ? AND held_count > 0
            """, id) == 1;
}

/**
 * 批量释放 n 个占用；held_count >= n 才生效，返回是否实际释放，杜绝变负/重复释放。
 */
public boolean releaseN(long id, int n) {
    if (n <= 0) {
        return true;
    }
    return jdbc.update("""
            UPDATE quota_account SET held_count = held_count - ?
            WHERE id = ? AND held_count >= ?
            """, n, id, n) == 1;
}

